+static bool
+is_thread_packet(packet_info *pinfo)
+{
+    if (pinfo == NULL || pinfo->layers == NULL)
+        return false;
+
+    return (proto_is_frame_protocol(pinfo->layers, "wpan") ||
+        proto_is_frame_protocol(pinfo->layers, "6lowpan") ||
+        proto_is_frame_protocol(pinfo->layers, "trel") ||
+        proto_is_frame_protocol(pinfo->layers, "thread") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_coap") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_meshcop") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_nm") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_address") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_diagnostic") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_bl") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_bcn") ||
+        proto_is_frame_protocol(pinfo->layers, "thread_nwd") ||
+        proto_is_frame_protocol(pinfo->layers, "mle"));
+}
+
+static bool
+dissect_thread_coap_heur(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    coap_info *coinfo;
+    const char *uri;
+    char **tokens;
+
+    if (!is_thread_packet(pinfo))
+        return false;
+
+    coinfo = (coap_info *)p_get_proto_data(wmem_file_scope(), pinfo, proto_coap, 0);
+    if (!coinfo || !coinfo->uri_path_strbuf)
+        return false;
+
+    uri = wmem_strbuf_get_str(coinfo->uri_path_strbuf);
+    tokens = wmem_strsplit(pinfo->pool, uri, "/", 3);
+    if (g_strv_length(tokens) < 2)
+        return false;
+
+    /* Check if the namespace belongs to Thread (e.g., 'c', 'a', 'n', 'b', 'd') */
+    if (!dissector_get_string_handle(thread_coap_namespace, tokens[1]))
+        return false;
+
+    dissect_thread_coap(tvb, pinfo, tree, NULL);
+    return true;
+}
+
+static int
+dissect_thread_tmf(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    /* Only decode as CoAP if this packet belongs to a Thread protocol stack */
+    if (!is_thread_packet(pinfo))
+        return 0;
+
+    return call_dissector(coap_handle, tvb, pinfo, tree);
+}
